<div class="page-heading"><div><span class="eyebrow">SUIVI COMMERCIAL</span><h1>Pipeline Kanban</h1><p>Faites glisser une carte vers un autre statut pour mettre à jour le suivi.</p></div></div><div class="kanban" id="kanban"><?php foreach(['nouveau','a_contacter','contacte','interesse','rdv','client','refuse'] as $status):$subset=array_filter($rows,fn($p)=>$p['statut_prospection']===$status);?><section class="kanban-col" data-status="<?=$status?>"><header><span class="status-dot status-<?=$status?>"></span><b><?=e(status_label($status))?></b><span class="kanban-count"><?=count($subset)?></span></header><div class="kanban-drop"><?php foreach($subset as $p):?><article class="kanban-card" draggable="true" data-id="<?=$p['id']?>"><a href="?r=prospect&id=<?=$p['id']?>"><b><?=e($p['nom'])?></b></a><small><?=e($p['categorie'])?> · <?=e($p['ville'])?></small><?php if($p['telephone']):?><a class="kanban-phone" href="tel:<?=e($p['telephone'])?>">☎ <?=e($p['telephone'])?></a><?php endif;?></article><?php endforeach;?></div></section><?php endforeach;?></div><div id="kanban-message" class="toast hidden"></div>
